  1	package com.loja.orderservice.model;
  2	
  3	public enum OrderStatus {
  4	    AWAITING_PAYMENT,
  5	    PAID,
  6	    SHIPPED,
  7	    DELIVERED,
  8	    CANCELLED
  9	}
 10	package com.loja.orderservice.model;
 11	
 12	public enum NotificationStatus {
 13	    NEW,
 14	    READ
 15	}
  1	package com.loja.orderservice.service;
  2	
  3	import com.loja.orderservice.dto.*;
  4	import com.loja.orderservice.entity.*;
  5	import com.loja.orderservice.exception.BusinessException;
  6	import com.loja.orderservice.model.*;
  7	import com.loja.orderservice.repository.*;
  8	import org.springframework.http.HttpStatus;
  9	import org.springframework.stereotype.Service;
 10	import org.springframework.transaction.annotation.Transactional;
 11	
 12	import java.math.BigDecimal;
 13	import java.math.RoundingMode;
 14	import java.time.Duration;
 15	import java.time.Instant;
 16	import java.util.*;
 17	
 18	@Service
 19	public class OrderService {
 20	
 21	    private static final BigDecimal ZERO = BigDecimal.ZERO.setScale(2, RoundingMode.HALF_EVEN);
 22	
 23	    private final OrderRepository orderRepository;
 24	    private final ProductRepository productRepository;
 25	    private final CustomerRepository customerRepository;
 26	    private final CheckoutCalculator checkoutCalculator;
 27	    private final NotificationService notificationService;
 28	
 29	    public OrderService(OrderRepository orderRepository,
 30	                        ProductRepository productRepository,
 31	                        CustomerRepository customerRepository,
 32	                        CheckoutCalculator checkoutCalculator,
 33	                        NotificationService notificationService) {
 34	        this.orderRepository = orderRepository;
 35	        this.productRepository = productRepository;
 36	        this.customerRepository = customerRepository;
 37	        this.checkoutCalculator = checkoutCalculator;
 38	        this.notificationService = notificationService;
 39	    }
 40	
 41	    public SummaryResponse calculateSummary(CheckoutRequest request) {
 42	        OrderSummary summary = checkoutCalculator.calculate(request);
 43	        return toSummaryResponse(summary);
 44	    }
 45	
 46	    @Transactional
 47	    public OrderResponse createOrder(CheckoutRequest request) {
 48	        OrderSummary summary = checkoutCalculator.calculate(request);
 49	
 50	        Order order = new Order();
 51	        order.setCustomerCpf(request.getCustomer().getCpf());
 52	        order.setCustomerEmail(request.getCustomer().getEmail());
 53	        order.setZipCode(request.getZipCode());
 54	        order.setRegion(request.getRegion());
 55	        order.setShippingMethod(request.getShippingMethod());
 56	        order.setCoupon(request.getCoupon());
 57	        order.setPaymentMethod(request.getPaymentMethod());
 58	        order.setClubTier(request.getClubTier());
 59	        order.setSummary(summary);
 60	
 61	        for (var item : request.getItems()) {
 62	            order.getItems().add(new OrderItem(item.getSku(), item.getQuantity()));
 63	        }
 64	
 65	        Customer customer = customerRepository.findById(request.getCustomer().getCpf())
 66	                .orElse(new Customer(request.getCustomer().getCpf()));
 67	        customerRepository.save(customer);
 68	
 69	        order = orderRepository.save(order);
 70	
 71	        return toOrderResponse(order);
 72	    }
 73	
 74	    @Transactional(readOnly = true)
 75	    public OrderResponse getOrder(Long id) {
 76	        Order order = orderRepository.findById(id)
 77	                .orElseThrow(() -> new BusinessException("ORDER_NOT_FOUND", HttpStatus.NOT_FOUND));
 78	        return toOrderResponse(order);
 79	    }
 80	
 81	    @Transactional(noRollbackFor = BusinessException.class)
 82	    public OrderResponse processPayment(Long id, PaymentRequest request) {
 83	        if (request.getTransactionId() == null || request.getPaidAt() == null) {
 84	            throw new BusinessException("INVALID_ORDER", HttpStatus.UNPROCESSABLE_ENTITY);
 85	        }
 86	
 87	        Order order = orderRepository.findById(id)
 88	                .orElseThrow(() -> new BusinessException("ORDER_NOT_FOUND", HttpStatus.NOT_FOUND));
 89	
 90	        if (order.getLastTransactionId() != null &&
 91	            order.getLastTransactionId().equals(request.getTransactionId())) {
 92	            return toOrderResponse(order);
 93	        }
 94	
 95	        if (order.getStatus() != OrderStatus.AWAITING_PAYMENT) {
 96	            throw new BusinessException("OPERATION_NOT_ALLOWED", HttpStatus.CONFLICT);
 97	        }
 98	
 99	        Duration elapsed = Duration.between(order.getCreatedAt(), request.getPaidAt());
100	        if (elapsed.compareTo(Duration.ofHours(48)) > 0) {
101	            order.setStatus(OrderStatus.CANCELLED);
102	            order.setLastTransactionId(request.getTransactionId());
103	            orderRepository.save(order);
104	            notificationService.notifyCustomer(order.getCustomerCpf(), NotificationType.ORDER_CANCELLED, order.getId());
105	            throw new BusinessException("ORDER_EXPIRED", HttpStatus.CONFLICT);
106	        }
107	
108	        try {
109	            reserveStock(order);
110	        } catch (BusinessException e) {
111	            order.setStatus(OrderStatus.CANCELLED);
112	            order.setLastTransactionId(request.getTransactionId());
113	            orderRepository.save(order);
114	            notificationService.notifyCustomer(order.getCustomerCpf(), NotificationType.ORDER_CANCELLED, order.getId());
115	            throw e;
116	        }
117	
118	        Customer customer = customerRepository.findByCpfForUpdate(order.getCustomerCpf())
119	                .orElse(new Customer(order.getCustomerCpf()));
120	        customer.addCredit(order.getSummary().getNextPurchaseCredit());
121	        customerRepository.save(customer);
122	
123	        order.setStatus(OrderStatus.PAID);
124	        order.setLastTransactionId(request.getTransactionId());
125	        orderRepository.save(order);
126	
127	        notificationService.notifyCustomer(order.getCustomerCpf(), NotificationType.PAYMENT_APPROVED, order.getId());
128	
129	        return toOrderResponse(order);
130	    }
131	
132	    @Transactional
133	    public OrderResponse shipOrder(Long id, ShipmentRequest request) {
134	        if (request.getTrackingCode() == null) {
135	            throw new BusinessException("INVALID_ORDER", HttpStatus.UNPROCESSABLE_ENTITY);
136	        }
137	
138	        Order order = orderRepository.findById(id)
139	                .orElseThrow(() -> new BusinessException("ORDER_NOT_FOUND", HttpStatus.NOT_FOUND));
140	
141	        if (order.getStatus() != OrderStatus.PAID) {
142	            throw new BusinessException("OPERATION_NOT_ALLOWED", HttpStatus.CONFLICT);
143	        }
144	
145	        order.setStatus(OrderStatus.SHIPPED);
146	        order.setTrackingCode(request.getTrackingCode());
147	        orderRepository.save(order);
148	
149	        notificationService.notifyCustomer(order.getCustomerCpf(), NotificationType.ORDER_SHIPPED, order.getId());
150	
151	        return toOrderResponse(order);
152	    }
153	
154	    @Transactional
155	    public OrderResponse deliverOrder(Long id) {
156	        Order order = orderRepository.findById(id)
157	                .orElseThrow(() -> new BusinessException("ORDER_NOT_FOUND", HttpStatus.NOT_FOUND));
158	
159	        if (order.getStatus() != OrderStatus.SHIPPED) {
160	            throw new BusinessException("OPERATION_NOT_ALLOWED", HttpStatus.CONFLICT);
161	        }
162	
163	        order.setStatus(OrderStatus.DELIVERED);
164	        orderRepository.save(order);
165	
166	        return toOrderResponse(order);
167	    }
168	
169	    @Transactional
170	    public OrderResponse cancelOrder(Long id) {
171	        Order order = orderRepository.findById(id)
172	                .orElseThrow(() -> new BusinessException("ORDER_NOT_FOUND", HttpStatus.NOT_FOUND));
173	
174	        if (order.getStatus() == OrderStatus.SHIPPED || order.getStatus() == OrderStatus.DELIVERED) {
175	            throw new BusinessException("OPERATION_NOT_ALLOWED", HttpStatus.CONFLICT);
176	        }
177	
178	        if (order.getStatus() == OrderStatus.CANCELLED) {
179	            return toOrderResponse(order);
180	        }
181	
182	        if (order.getStatus() == OrderStatus.PAID) {
183	            releaseStock(order);
184	
185	            Customer customer = customerRepository.findByCpfForUpdate(order.getCustomerCpf())
